settings.custom_css:
selector .elementor-container {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: stretch !important;
}
selector .elementor-row {
  display: flex !important;
  flex-wrap: wrap !important;
  align-items: stretch !important;
}
selector .elementor-column {
  display: flex !important;
  height: auto !important;
}

selector {
  display: flex !important;
  flex-direction: column !important;
  height: 100% !important;
  transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;
}
selector > .elementor-widget-wrap {
  display: flex !important;
  flex-direction: column !important;
  flex-grow: 1 !important;
  height: 100% !important;
  width: 100% !important;
}
/* USER REQUIREMENT: Hover GROW on icon with GREEN background fill */
selector .elementor-icon-box-icon {
  transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;
  border: 1px solid rgba(56, 212, 216, 0.25) !important;
}
selector:hover .elementor-icon-box-icon,
selector .elementor-icon-box-icon:hover {
  transform: scale(1.15) !important;
  background-color: #179A9E !important;
  border-color: #179A9E !important;
  box-shadow: 0 8px 24px rgba(23, 154, 158, 0.5) !important;
}
selector:hover .elementor-icon-box-icon svg,
selector:hover .elementor-icon-box-icon i,
selector .elementor-icon-box-icon:hover svg,
selector .elementor-icon-box-icon:hover i {
  color: #FFFFFF !important;
  fill: #FFFFFF !important;
}

